create or replace function private.job_archive_stamp() returns trigger language plpgsql security definer set search_path = '' as $$ begin select e.name into new.owner_name from public.counselor_accounts a join public.edoc_employees e on e.id=a.employee_id where a.user_id=new.owner_id; if TG_OP='UPDATE' then if new.job is not distinct from old.job and new.is_shared is distinct from old.is_shared then new.saved_at=old.saved_at; else new.saved_at=now(); end if; else new.saved_at=now(); end if; return new; end; $$;
